        "label": "Target Type",
        "customPicklistValuesString": [
          "Related List",
          "Info"
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Source_Type__c",
      "toolTip": "Related List: For the use of related records as the source. Interim Cards: For use of Interim fields as the source.",
      "customFieldParams": {
        "type": "text",
        "label": "Source Type",
        "customPicklistValuesString": [
          "Related List",
          "Interim Cards"
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Target_Lookup_API_Name__c",
      "toolTip": "API Name of lookup to Interim if target object is not a Contact. Only use for Related List Target types.",
      "customFieldParams": {
        "type": "text",
        "label": "Target Lookup API Name"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Source_Lookup_API_Name__c",
      "toolTip": "API Name of lookup to Interim if source object is not an Interim. Only use for Related List Source types.",
      "customFieldParams": {
        "type": "text",
        "label": "Source Lookup API Name"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Preferred_Field_API_Name__c",
      "toolTip": "For use with the Interim Card source tab type, and the Related List target tab type. This denotes the field that is used on the related SObject to mark a record as preferred.",
      "customFieldParams": {
        "type": "text",
        "label": "Preferred Field API Name"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Preferred_Record_Picklist_API_Name__c",
      "toolTip": "For use with the Interim Card source tab type and the Related List target tab type. API name of a picklist on the Interim denotes a preferred record. Picklist values should be in the following form. \"Phone 1\", or \"Address Relation 2\".",
      "customFieldParams": {
        "type": "text",
        "label": "Preferred Record Picklist API Name"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Parent_Object_Lookup_API_Name__c",
      "toolTip": "If the target is a junction object, use this to specify what field looks up to the parent SObject.",
      "customFieldParams": {
        "type": "text",
        "label": "Parent Object Lookup API Name"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Order__c",
      "toolTip": "Ordering that the tabs will appear in.",
      "customFieldParams": {
        "type": "number",
        "label": "Order"
      }
    }
